const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>People Prime | Outreach</title><meta name=\"description\" content=\"People Prime America startup prospect discovery and approval\"><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='10' fill='%232255e8'/%3E%3Ctext x='10' y='29' font-size='27' fill='white'%3EP%3C/text%3E%3C/svg%3E\"><style>:root{color-scheme:dark;--ink:#effbf6;--muted:#afc9c4;--lime:#d9fa86;--line:#a9e9dc26;--surface:#0c2c2ef0}*{box-sizing:border-box}body{margin:0;background:#061c23;color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background-image:radial-gradient(ellipse at 30% -30%,#d1fd8a44,transparent 55%),radial-gradient(ellipse at 100% 0,#02b9b136,transparent 50%);background-attachment:fixed}button,input,select,textarea{font:inherit}button{cursor:pointer}button,a,input,textarea,select{transition:background .18s,border-color .18s,box-shadow .18s,transform .18s}button:disabled{opacity:.45;cursor:not-allowed}aside{position:fixed;inset:0 auto 0 0;width:244px;background:#061a20ed;border-right:1px solid var(--line);padding:38px 20px 24px;display:flex;flex-direction:column;z-index:2}.brand{font-size:27px;font-weight:780;letter-spacing:-1.3px;padding:0 10px}.brand span{color:var(--lime)}.brand small{display:block;font-size:11px;font-weight:550;letter-spacing:2.4px;color:#a4c2be;margin:5px 0 50px}nav button{display:block;width:100%;text-align:left;border:1px solid transparent;background:none;color:#b0c9c6;padding:13px 14px;border-radius:12px;margin-bottom:8px;font-size:14px;font-weight:550}nav button:hover{background:#183d3e;color:white}nav button.active{background:var(--lime);color:#172d23;box-shadow:0 6px 25px #c9fb6920;font-weight:750}aside footer{margin-top:auto;font-size:13px;color:#9dbdb8;padding:24px 10px 0;border-top:1px solid var(--line)}main{margin-left:244px;padding:28px 36px 60px;max-width:1900px}.top{display:flex;justify-content:space-between;align-items:center;padding-bottom:20px}.crumb{color:#a4c7c1;font-size:14px}.crumb b{color:#eaf9f4;font-weight:550}.avatar{display:grid;place-items:center;background:#244f49;border:1px solid #84ba9d66;color:var(--lime);border-radius:14px;width:44px;height:44px;font-size:14px;font-weight:750}.notice{margin:10px 0 22px;background:#102d32a8;border:1px solid var(--line);padding:12px 17px;border-radius:12px;font-size:13px;color:#b9d5cf}.head{display:flex;justify-content:space-between;align-items:center;gap:25px;margin:26px 0}.head h1{font-size:clamp(29px,3.4vw,48px);font-weight:680;letter-spacing:-1.9px;line-height:1.15;margin:0}.head p{margin-top:14px;max-width:620px}#app>.head:first-child{position:relative;isolation:isolate;padding:34px;border:1px solid #8ddbc54a;border-radius:24px;min-height:185px;background:radial-gradient(ellipse at 0 0,#b3eda524,transparent 68%),linear-gradient(120deg,#19605eaa,#0b2c36bb);box-shadow:0 20px 50px #00171940;overflow:hidden}#app>.head:first-child:before{content:'';position:absolute;z-index:-1;inset:0;background:repeating-linear-gradient(130deg,transparent 0 3px,#a8ffcb07 3px 4px);pointer-events:none}h2{font-size:19px;font-weight:650;letter-spacing:-.35px;margin:0 0 16px}p{margin:8px 0;color:var(--muted)}.btn{border:1px solid #729e9666;background:#19413f;color:#e5f6ec;border-radius:10px;padding:10px 16px;font-weight:650;font-size:14px;white-space:normal}.btn:hover:not(:disabled){background:#25554e;transform:translateY(-1px);border-color:#b3d0b8}.primary{background:var(--lime);color:#1b3222;border-color:var(--lime);box-shadow:0 5px 25px #cbf77414}.primary:hover:not(:disabled){background:#e7ffad;border-color:#e7ffad}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:22px 0 26px}.stat,.panel{background:linear-gradient(145deg,#143b3ded,#0c292eef);border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 8px 22px #00111925;min-width:0}.stat{position:relative;overflow:hidden;min-height:158px}.stat:first-child{background:linear-gradient(125deg,#dafa96,#abebae);border-color:#dafa96;color:#193629}.stat:first-child small,.stat:first-child span{color:#315840}.stat:first-child strong{color:#102a1d}.stat small{color:#bed9d1;font-size:14px}.stat strong{display:block;font-size:42px;line-height:1.2;font-weight:650;letter-spacing:-1.5px;margin:14px 0 8px}.stat span{color:#98bdb7;font-size:13px}.stat:after{content:'';position:absolute;right:-20px;bottom:-35px;width:100px;height:100px;border-radius:50%;border:1px solid #c4f5d322;box-shadow:0 0 0 17px #c4f5d308}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:20px}.toolbar{display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap}input,select,textarea{border:1px solid #58857d88;border-radius:10px;padding:12px;background:#08282d;color:#f2fcf7;max-width:100%}input:focus,textarea:focus,select:focus{outline:2px solid #d9fa8699;outline-offset:2px}input::placeholder,textarea::placeholder{color:#7fa9a2}table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}th{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#98c2b7;background:#08262ca6;font-weight:600}td,th{padding:18px 13px;border-bottom:1px solid var(--line)}td strong{display:block;font-size:15px;margin-bottom:4px}td small{color:#9bbdb6}tbody tr:hover{background:#72cd9e08}.tablewrap{overflow:auto}.pill{display:inline-block;padding:5px 10px;border:1px solid #5fbcba33;border-radius:30px;background:#17474d;color:#b9efe7;font-size:12px;font-weight:550;white-space:nowrap}.green{background:#c9f79b1c;border-color:#c9f79b33;color:#d1f89e}.amber{background:#f7d78818;border-color:#f7d78833;color:#f1d68f}.row{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:17px 0;border-bottom:1px solid var(--line);font-size:14px}.row span:last-child{overflow-wrap:anywhere;text-align:right}.muted{font-size:14px;color:#a7c5bc}.board{display:grid;grid-template-columns:repeat(4,minmax(190px,1fr));gap:16px;overflow:auto}.column{background:#0d2c32aa;border:1px solid var(--line);border-radius:20px;padding:20px}.column>h2{border-bottom:2px solid #b4deca44;padding-bottom:16px}.column:nth-child(2)>h2{border-color:#62d5ca}.column:nth-child(3)>h2{border-color:#c6efa3}.column:nth-child(4)>h2{border-color:#e1cc91}.card{background:#14393c;border:1px solid #79c9ae30;padding:18px;border-radius:14px;margin:14px 0}.card select{width:100%;margin-top:14px;font-size:13px}.formgrid,.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px}label{display:block;font-size:14px;font-weight:600;margin-bottom:16px;color:#d8eee4}label input,label textarea,label select{display:block;width:100%;margin-top:8px;font-weight:400}textarea{min-height:220px;resize:vertical}dialog{color:var(--ink);background:#0e2c31;border:1px solid #659b8c80;border-radius:24px;padding:30px;width:min(560px,92vw);max-height:90vh;overflow:auto;box-shadow:0 25px 100px #0009}dialog::backdrop{background:#00151cc9;backdrop-filter:blur(5px)}.toast{position:fixed;bottom:24px;right:24px;background:#d9fa86;color:#193127;border:1px solid #e8ffbc;padding:16px 22px;border-radius:14px;max-width:min(450px,90vw);box-shadow:0 8px 40px #0006;z-index:5}button:focus-visible,a:focus-visible{outline:3px solid #e5ff9f;outline-offset:3px}.empty{padding:45px 20px;text-align:center;border:1px dashed #80b5a344;border-radius:14px;margin-top:18px}.empty h2{color:#d7eecf}.error{background:#5b262c;color:#ffe0dc;padding:14px;border-radius:12px}a{color:#d4f49d;text-underline-offset:4px}.chips{display:flex;gap:8px;flex-wrap:wrap}.chips span{background:#a1e7d015;border:1px solid #87c8b333;color:#ddf3de;padding:8px 12px;border-radius:9px;font-size:14px}input[type=checkbox]{display:inline;width:auto;margin:0 8px 0 0;accent-color:var(--lime)}@media(min-width:1500px){main{padding:34px 48px 70px}.head h1{font-size:48px}}@media(max-width:1100px){aside{width:210px}main{margin-left:210px;padding:24px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.head{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}}@media(max-width:850px){.review-grid,.formgrid{grid-template-columns:1fr}}@media(max-width:640px){aside{position:static;width:auto;padding:22px 16px 12px}.brand small{margin-bottom:20px}nav{display:flex;overflow:auto;gap:6px}nav button{width:auto;flex-shrink:0;margin:0;white-space:nowrap}aside footer{display:none}main{margin:0;padding:16px}.top{padding:0 0 12px}#app>.head:first-child{padding:24px;min-height:auto;border-radius:18px}.head h1{font-size:32px;letter-spacing:-1.2px}.stats{gap:12px}.stat,.panel{padding:18px;border-radius:16px}.stat strong{font-size:36px}.board{grid-template-columns:repeat(4,240px)}.notice{font-size:12px}.row{align-items:flex-start}.row span:last-child{max-width:55%}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n\n/* Quiet neutral surfaces with limited teal accents. */\n:root{color-scheme:light;--ink:#232b32;--muted:#687078;--lime:#3c807b;--line:#dee2e4;--surface:#fff}body{background:#f2f3f4;color:var(--ink)}aside{background:#20272c;border-color:#323b41;color:#f4f6f7}.brand span{color:#9ccbc5}.brand small,aside footer{color:#9facb2}aside footer{border-color:#ffffff18}nav button{color:#b9c4c9}nav button:hover{background:#303c42}nav button.active{background:#deebe8;color:#234b46;box-shadow:none}.crumb{color:#778189}.crumb b{color:#313c44}.avatar{background:#e4e9e8;border-color:#d2dcda;color:#365c55}.notice{background:#e9edef;border-color:#dce2e5;color:#617079}#app>.head:first-child{background:linear-gradient(110deg,#fff,#edf0f0);border-color:#dce2e5;box-shadow:0 8px 25px #23333d05;min-height:160px}#app>.head:first-child:before{display:none}.head h1{font-size:clamp(29px,3vw,42px)}.stat,.panel{background:#fff;border-color:#dee3e5;box-shadow:0 5px 18px #172b3705}.stat:first-child{background:#e5eeeb;border-color:#d8e4df;color:#243d34}.stat:first-child small,.stat:first-child span{color:#5c7168}.stat:first-child strong{color:#243d34}.stat small{color:#67737a}.stat strong{color:#253038}.stat span{color:#7c878c}.stat:after{display:none}.btn{background:#fff;color:#36454c;border-color:#cbd4d8;box-shadow:none}.btn:hover:not(:disabled){background:#eef2f2;border-color:#889d9a}.primary{background:#36746e;color:#fff;border-color:#36746e}.primary:hover:not(:disabled){background:#2e645f;border-color:#2e645f}.chips span{background:#f0f3f3;border-color:#dce5e2;color:#4c625d}.pill{background:#eef1f4;border-color:#dce3e8;color:#536677}.green{background:#e7f0e9;border-color:#d3e4d7;color:#447256}.amber{background:#f7f0df;border-color:#e9dfbf;color:#887031}th{background:#f5f7f8;color:#74818a}td small,.muted{color:#748089}tbody tr:hover{background:#f6f8f8}.row{border-color:#e2e7e9}input,select,textarea{background:#fbfcfc;color:#27353c;border-color:#cbd5d8}input::placeholder,textarea::placeholder{color:#87949a}a{color:#32766f}.column{background:#e9edef;border-color:#dce2e5}.column>h2{border-color:#b7c2c8}.column:nth-child(2)>h2{border-color:#99b6c3}.column:nth-child(3)>h2{border-color:#9ebba6}.column:nth-child(4)>h2{border-color:#c7b790}.card{background:#fff;border-color:#d8e1e3}dialog{background:#fff;color:#28343c;border-color:#dce3e6}label{color:#46555d}dialog::backdrop{background:#15232b99}.empty{border-color:#d0dcdf}.empty h2{color:#46575c}.toast{background:#243c3b;color:#fff;border-color:#476966}.error{background:#fae9e7;color:#8a3936}button:focus-visible,a:focus-visible,input:focus,textarea:focus,select:focus{outline-color:#508c8799}.job-evidence{background:#f6f8f8;border:1px solid #e0e6e6;border-radius:10px;padding:14px;margin:12px 0}.job-evidence p{font-size:14px}.scope-note{max-width:680px}.sources-summary{font-size:13px;color:#748089}#scope{min-width:240px}\n</style></head><body><aside><div class=\"brand\">people<span>prime</span><small>OUTREACH WORKSPACE</small></div><nav id=\"nav\"></nav><footer>People Prime America<br><br>Private workspace<br>Approval required for outreach</footer></aside><main><div class=\"top\"><span class=\"crumb\">Workspace / <b id=\"crumb\">Discovery</b></span><span class=\"avatar\">JA</span></div><div class=\"notice\">Saved prospect research · Every email needs approval · Outlook sending is not connected</div><div id=\"app\"><p>Loading your workspace…</p></div></main><dialog id=\"modal\"></dialog><div id=\"toast\" class=\"toast\" hidden></div><script>const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet state={view:'Discovery',connected:false,prospects:[],lastRun:null,busy:false,error:'',loaded:false,budget:null,source:'ats',scope:'remote',atsBoardCount:0},selected=null;\nconst tabs=['Discovery','Approval queue','Approved','Pipeline','Replies','Team & connections'];\nconst when=x=>x?new Date(x).toLocaleString():'Not yet';\nfunction toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,6000)}\nasync function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('The workspace could not load. Refresh the page or sign in again.')}if(!r.ok)throw Error(data.error||'Please try again.');return data}\nasync function load(){try{Object.assign(state,await api('state'),{loaded:true,error:''})}catch(e){state.error=e.message}render()}\nfunction go(v){state.view=v;render()}\nfunction head(t,d,b=''){return `<div class=\"head\"><div><h1>${t}</h1><p>${d}</p></div>${b}</div>`}\nfunction empty(t,d){return `<div class=\"empty\"><h2>${t}</h2><p>${d}</p></div>`}\nfunction badge(t){return `<span class=\"pill ${t==='Approved'?'green':t==='Opted out'?'amber':''}\">${esc(t)}</span>`}\nfunction table(ps){return `<div class=\"tablewrap\"><table><thead><tr><th>Company</th><th>Contact</th><th>Status</th><th>Found</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.company)}</strong><small>${p.hiringJobs?`${p.remoteJobCount||0} matching remote tech roles · checked ${esc(new Date(p.hiringCheckedAt).toLocaleDateString())}`:`${esc(p.industry||'Technology candidate')} · ${esc(p.employees??'Unknown')} employees`}</small></td><td>${esc(p.contact?.name||'Contact research needed')}<br><small>${esc(p.contact?.title||'')}</small></td><td>${badge(p.status)}</td><td>${esc(new Date(p.discoveredAt).toLocaleDateString())}</td><td><button class=\"btn\" data-review=\"${esc(p.id)}\">Review</button></td></tr>`).join('')}</tbody></table></div>`}\nfunction render(){ $('#nav').innerHTML=tabs.map((v,i)=>`<button data-view=\"${v}\" class=\"${v===state.view?'active':''}\">${['◎','☑','✓','▥','☷','⚙'][i]} &nbsp; ${v}${v==='Approval queue'?' · '+state.prospects.filter(p=>p.status==='Needs review').length:''}</button>`).join('');$('#crumb').textContent=state.view;let h='';const action=`<button class=\"btn primary\" id=\"discover\" ${state.busy||(state.source==='apollo'&&(!state.connected||state.budget?.used>=100))?'disabled':''}>${state.busy?'Finding companies…':'Find up to 40 companies'}</button>`;\nif(state.view==='Discovery')h=head('Find your next tech client.','Find employers through their current remote tech openings.',action)+`<div class=\"stats\"><div class=\"stat\"><small>Companies found</small><strong>${state.prospects.length}</strong><span>Duplicates excluded</span></div><div class=\"stat\"><small>Awaiting review</small><strong>${state.prospects.filter(p=>p.status==='Needs review').length}</strong><span>No outreach authorized yet</span></div><div class=\"stat\"><small>Approved messages</small><strong>${state.prospects.filter(p=>p.status==='Approved').length}</strong><span>Held until Outlook setup</span></div><div class=\"stat\"><small>Apollo</small><strong style=\"font-size:22px\">${state.connected?'Connected':'Not connected'}</strong><span>${state.connected?'Available for contact research':'Optional for job-board discovery'}</span></div></div><div class=\"grid\"><section class=\"panel\"><h2>Hiring signals to search</h2><div class=\"toolbar\"><label>Source<select id=\"source\"><option value=\"ats\" ${state.source==='ats'?'selected':''}>Live employer job boards</option><option value=\"apollo\" ${state.source==='apollo'?'selected':''}>Apollo company database</option></select></label>${state.source==='ats'?`<label>Remote eligibility<select id=\"scope\"><option value=\"remote\" ${state.scope==='remote'?'selected':''}>Remote across countries / regions</option><option value=\"worldwide\" ${state.scope==='worldwide'?'selected':''}>Explicitly worldwide only</option></select></label>`:''}</div>${state.source==='ats'?`<div class=\"chips\"><span>Current ATS listings</span><span>Technical roles</span><span>Remote hiring</span><span>0 Apollo credits</span></div><p class=\"scope-note\">Checks ${state.atsBoardCount} tracked employer boards on Ashby and saves up to 40 matching companies. This is a live scan of those boards, not an internet-wide search. Company size and headquarters are not filtered in this mode.</p><p class=\"muted\">Worldwide means the job’s location explicitly says global or worldwide. Other remote jobs may limit country, region, or time zone. Review the linked listing before outreach.</p>`:`<div class=\"chips\"><span>United States HQ</span><span>20–500 employees</span><span>Software · SaaS · AI</span><span>Technical hiring</span></div><p>Apollo’s company filters do not verify remote eligibility. Each company search reserves one credit.</p>`}<p class=\"muted\">Startup fit and willingness to use staffing vendors still need your review. Existing companies and opt-outs are preserved.</p></section><section class=\"panel\"><h2>Connection & activity</h2><div class=\"row\"><span>Monthly credit allowance</span><b>${state.budget?.used??0} / 100 reserved</b></div><p class=\"muted\">Calendar month in Chicago time. Counts this tool’s paid requests from activation; other Apollo usage is excluded. Failed requests keep their reservation to avoid overspending.</p><div class=\"row\"><span>Apollo account</span>${badge(state.connected?'Connected':'Setup needed')}</div><div class=\"row\"><span>Last discovery</span><span>${esc(when(state.lastRun?.at))}</span></div>${state.lastRun?`<p>${state.lastRun.added} new companies saved from ${state.lastRun.returned} matches.${state.lastRun.source==='ATS'?` ${state.lastRun.refreshed||0} existing companies refreshed. ${state.lastRun.checked} boards checked; ${state.lastRun.failed} unavailable.`:''}</p>`:''}<button class=\"btn\" data-view=\"Team & connections\">${state.connected?'Manage connection':'Connect Apollo'}</button><p class=\"muted\">Discovery runs when you click above. Unattended daily discovery is not enabled yet.</p></section></div><section class=\"panel\" style=\"margin-top:20px\"><h2>${state.lastRun?.source==='ATS'?'Companies matching the latest scan':'Saved companies'}</h2>${state.prospects.length?table((state.lastRun?.source==='ATS'?state.prospects.filter(p=>state.lastRun.companyIds?.includes(p.id)):state.prospects).slice(0,40)):empty('Your prospect list starts here','Search live job boards to find employers with remote technical openings.')}</section>`;\nif(state.view==='Approval queue'||state.view==='Approved'){const ps=state.prospects.filter(p=>p.status===(state.view==='Approved'?'Approved':'Needs review'));h=head(state.view,state.view==='Approved'?'Exact recipient and message approved. Nothing has been sent.':'Check company fit, select a contact, and review the exact message.')+`<section class=\"panel\">${ps.length?table(ps):empty(state.view==='Approved'?'No approved messages yet':'Your review queue is clear','Discover companies to add new prospects.')}</section><section class=\"panel\" style=\"margin-top:20px\"><h2>Excluded prospects</h2>${state.prospects.some(p=>['Rejected','Opted out'].includes(p.status))?table(state.prospects.filter(p=>['Rejected','Opted out'].includes(p.status))):'<p>No rejected or opted-out prospects.</p>'}</section>`}\nif(state.view==='Pipeline'){const stages=['New','Contacted','Replied','Meeting'];h=head('Client pipeline','Track conversations manually while Outlook is disconnected.')+`<div class=\"board\">${stages.map(stage=>`<section class=\"column\"><h2>${stage}</h2>${state.prospects.filter(p=>!['Rejected','Opted out'].includes(p.status)&&(p.stage||'New')===stage).map(p=>`<div class=\"card\"><b>${esc(p.company)}</b><p>${esc(p.contact?.name||'Contact needed')}</p>${badge(p.status)}<select aria-label=\"Stage for ${esc(p.company)}\" data-stage=\"${esc(p.id)}\">${stages.map(s=>`<option ${stage===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')||'<p>No prospects here.</p>'}</section>`).join('')}</div>`}\nif(state.view==='Replies')h=head('Replies','Real conversations will appear after Outlook is connected.')+`<section class=\"panel\">${empty('Mailbox connection needed','No mailbox is being read and no follow-up emails are scheduled.')}<button class=\"btn\" data-view=\"Team & connections\">Connection status</button></section>`;\nif(state.view==='Team & connections')h=head('Team & connections','Public job boards power hiring discovery. Apollo helps find contacts.')+`<div class=\"grid\"><section class=\"panel\"><h2>Apollo ${state.connected?'· connected':''}</h2><p>Your API key is encrypted on the server and is never displayed after saving.</p><form id=\"connect\"><label>Apollo API key<input id=\"apikey\" type=\"password\" autocomplete=\"off\" required placeholder=\"Enter your API key here, not in chat\"></label><p class=\"muted\">Allow company search, people search, and people enrichment. Connection testing uses a people search; company discovery begins only when you run it.</p><button class=\"btn primary\" ${state.busy?'disabled':''}>${state.connected?'Replace connection':'Connect Apollo'}</button></form>${state.connected?'<button class=\"btn\" style=\"margin-top:15px\" id=\"disconnect\">Disconnect Apollo</button>':''}<p><a href=\"https://developer.apollo.io/\" target=\"_blank\" rel=\"noopener\">Open Apollo developer settings</a></p><p class=\"muted\">API access depends on your Apollo account and key permissions.</p></section><section class=\"panel\"><h2>Monthly allowance</h2><p><b>${state.budget?.used??0} / 100 credits reserved</b> for ${esc(state.budget?.month||'this month')}.</p><p class=\"muted\">One credit reserved per company search or business-email enrichment attempt, using Apollo’s current standard pricing. Phone and waterfall enrichment stay off. Legacy plan pricing may differ; this counter is not your Apollo billing balance. Resets on the first of each month in Chicago time.</p><h2>Team & Outlook</h2><div class=\"row\"><span>Jahnavi · workspace owner</span>${badge('Not connected')}</div><p>Outlook authorization and team invitations are the next setup step. Approved messages stay saved here and cannot be sent by this version.</p><h2 style=\"margin-top:25px\">Approval rules</h2><p>Every initial message and every follow-up needs its own approval. Editing a message cancels its approval. Rejected and opted-out prospects stay excluded from discovery duplicates.</p></section></div>`;\n$('#app').innerHTML=(state.error?`<div class=\"error\">${esc(state.error)} <button class=\"btn\" id=\"retry\">Retry</button></div>`:'')+h;\ndocument.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));document.querySelectorAll('[data-stage]').forEach(s=>s.onchange=()=>changeStage(s.dataset.stage,s.value));if($('#source'))$('#source').onchange=e=>{state.source=e.target.value;render()};if($('#scope'))$('#scope').onchange=e=>{state.scope=e.target.value};if($('#retry'))$('#retry').onclick=load;if($('#discover'))$('#discover').onclick=discover;if($('#connect'))$('#connect').onsubmit=connect;if($('#disconnect'))$('#disconnect').onclick=disconnect;}\nasync function busy(fn){if(state.busy)return;state.busy=true;render();try{await fn()}catch(e){toast(e.message)}finally{state.busy=false;await load()}}\nasync function discover(){await busy(async()=>{const r=await api('discover',{source:state.source,scope:state.scope});toast(`${r.added} new companies saved.${r.source==='ATS'?` ${r.refreshed} existing companies refreshed; ${r.failed} boards unavailable.`:''}`)})}\nasync function connect(ev){ev.preventDefault();const key=$('#apikey').value;await busy(async()=>{await api('connect',{key});toast('Apollo connected. You can now run company discovery.');state.view='Discovery'})}\nasync function disconnect(){await busy(async()=>{await api('disconnect',{});toast('Apollo disconnected. Your saved prospects remain.')})}\nasync function changeStage(id,stage){const p=state.prospects.find(p=>p.id===id);try{await api('prospect',{id,revision:p.revision,action:'pipeline',stage});await load()}catch(e){toast(e.message);await load()}}\nfunction review(id){selected=state.prospects.find(p=>p.id===id);const p=selected;const excluded=['Rejected','Opted out'].includes(p.status);$('#modal').style.width='min(1000px,94vw)';$('#modal').innerHTML=`<div class=\"head\"><div><h2>${esc(p.company)}</h2>${badge(p.status)}</div><button class=\"btn\" id=\"close\">Close</button></div><div id=\"modalerror\" role=\"alert\"></div><div class=\"review-grid\"><section><h2>Why this company</h2><p>${esc(p.signal)}</p><p class=\"muted\">Found ${esc(when(p.discoveredAt))}</p><p><a href=\"${esc(p.source)}\" target=\"_blank\" rel=\"noopener\">${p.hiringSource?'View employer job board':'Review company in Apollo'}</a>${p.website?` · <a href=\"${esc(p.website)}\" target=\"_blank\" rel=\"noopener\">Company website</a>`:''}</p>${jobEvidence(p)}<label>Hiring evidence and company-fit notes<textarea id=\"evidence\" style=\"min-height:100px\" placeholder=\"Paste a careers-page link and the relevant roles. Note why the company is a startup fit.\">${esc(p.evidence)}</textarea></label><label><input id=\"fit\" type=\"checkbox\" ${p.fitReviewed?'checked':''}>I reviewed company fit, hiring evidence, and location restrictions</label><h2>Decision-maker</h2>${p.contact?`<p><b>${esc(p.contact.name)}</b><br>${esc(p.contact.title)}<br>${esc(p.contact.email||'No email returned')}<br>${badge(p.contact.emailStatus||'Unverified')}</p>`:'<p>No contact selected yet.</p>'}<button class=\"btn\" id=\"findcontacts\" ${excluded?'disabled':''}>${p.apolloId?'Find relevant contacts':'Find company in Apollo · 1 credit'}</button><div id=\"contacts\"></div></section><section><h2>Message for your approval</h2><label>Subject<input id=\"subject\" value=\"${esc(p.subject)}\"></label><label>Email<textarea id=\"message\">${esc(p.body)}</textarea></label><p class=\"muted\">Save edits before approving. Approval covers this exact recipient and text. Your business mailing address and Outlook sender must be configured before delivery.</p><div class=\"toolbar\"><button class=\"btn\" id=\"save\" ${excluded?'disabled':''}>Save changes</button><button class=\"btn primary\" id=\"approve\" ${excluded?'disabled':''}>Approve message</button></div><div class=\"toolbar\"><button class=\"btn\" id=\"reject\" ${excluded?'disabled':''}>Reject prospect</button><button class=\"btn\" id=\"suppress\" ${excluded?'disabled':''}>Mark opted out</button></div>${p.approval?`<p class=\"muted\">Approved ${esc(when(p.approval.at))}. Sending remains disabled.</p>`:''}</section></div>`;if(!$('#modal').open)$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();$('#save').onclick=()=>mutate('save',{subject:$('#subject').value,body:$('#message').value,evidence:$('#evidence').value,fitReviewed:$('#fit').checked});$('#approve').onclick=()=>{if($('#subject').value!==p.subject||$('#message').value!==p.body||$('#evidence').value!==p.evidence||$('#fit').checked!==p.fitReviewed)return modalError('Save your changes before approving.');mutate('approve')};$('#reject').onclick=()=>mutate('reject');$('#suppress').onclick=()=>mutate('suppress');$('#findcontacts').onclick=findContacts;}\nfunction modalError(t){$('#modalerror').className='error';$('#modalerror').textContent=t}\nasync function mutate(action,extra={}){const p=selected;document.querySelectorAll('#modal button').forEach(b=>b.disabled=true);try{await api('prospect',{id:p.id,revision:p.revision,action,...extra});await load();review(p.id);toast(action==='approve'?'Message approved and held. No email sent.':'Changes saved.')}catch(e){modalError(e.message);document.querySelectorAll('#modal button').forEach(b=>b.disabled=false)}}\nasync function findContacts(){const p=selected;$('#findcontacts').disabled=true;try{const r=await api('prospect',{id:p.id,revision:p.revision,action:p.apolloId?'contacts':'resolve'});if(r.companies){p.revision=r.revision;$('#contacts').innerHTML=r.companies.length?'<p>Confirm the correct company before searching for people:</p>'+r.companies.map(o=>`<div class=\"card\"><b>${esc(o.name)}</b><p>${esc(o.website||'Website unavailable')} · ${esc(o.country||'Location unavailable')}</p><button class=\"btn\" data-link=\"${esc(o.id)}\">Confirm this company</button></div>`).join(''):'<p>No company match found in Apollo. You can still review the hiring evidence and research contacts manually.</p>';document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>mutate('link',{organizationId:b.dataset.link}));return;}$('#contacts').innerHTML=r.contacts.length?r.contacts.map(c=>`<div class=\"card\"><b>${esc(c.name)}</b><p>${esc(c.title)}</p><p class=\"muted\">Business email lookup may use Apollo credits.</p><button class=\"btn\" data-enrich=\"${esc(c.id)}\">Select & find business email</button></div>`).join(''):'<p>No relevant contacts returned. Review the company in Apollo.</p>';document.querySelectorAll('[data-enrich]').forEach(b=>b.onclick=()=>mutate('enrich',{contactId:b.dataset.enrich}))}catch(e){modalError(e.message)}finally{$('#findcontacts').disabled=false}}\nfunction jobEvidence(p){if(!p.hiringJobs)return '';return `<h2 style=\"margin-top:22px\">Open remote roles</h2><p class=\"sources-summary\">Checked ${esc(when(p.hiringCheckedAt))}. A live listing is a hiring signal, not proof of agency demand.</p>${p.hiringJobs.map(j=>`<div class=\"job-evidence\"><a href=\"${esc(j.url)}\" target=\"_blank\" rel=\"noopener\">${esc(j.title)}</a><p>${esc(j.location)}</p>${badge(j.scope)}<p class=\"muted\">${j.publishedAt?'Published '+esc(when(j.publishedAt)):'Publication date not supplied'}</p></div>`).join('')}`}\nload();\n</script></body></html>";
